import{_ as i,c as a,a2 as e,o as t}from"./chunks/framework.CO0qOYmW.js";const n=JSON.parse('{"title":"浏览器原理","description":"","frontmatter":{"title":"浏览器原理","category":"浏览器","excerpt":"是指浏览器将 HTML、CSS、JavaScript 代码转换为可视化页面的过程。 渲染原理可以分为以下步骤： 解析 HTML 代码：浏览器将 HTML 代码解析为 DOM 树。 解析 CSS 代码：浏览器将 CSS 代码解析为 CSSOM..."},"headers":[],"relativePath":"articles/browser/02-render.md","filePath":"articles/browser/02-render.md","lastUpdated":1773591891000}'),o={name:"articles/browser/02-render.md"};function c(s,l,r,d,u,p){return t(),a("div",null,l[0]||(l[0]=[e('<h1 id="浏览器原理" tabindex="-1">浏览器原理 <a class="header-anchor" href="#浏览器原理" aria-label="Permalink to &quot;浏览器原理&quot;">​</a></h1><h2 id="一、浏览器渲染原理" tabindex="-1">一、浏览器渲染原理 <a class="header-anchor" href="#一、浏览器渲染原理" aria-label="Permalink to &quot;一、浏览器渲染原理&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">注意</p><ul><li>是指浏览器将 HTML、CSS、JavaScript 代码转换为可视化页面的过程。</li><li>渲染原理可以分为以下步骤：</li></ul><ol><li>解析 HTML 代码：浏览器将 HTML 代码解析为 DOM 树。</li><li>解析 CSS 代码：浏览器将 CSS 代码解析为 CSSOM 树。</li><li>合并 DOM 树和 CSSOM 树：将 DOM 树和 CSSOM 树合并为渲染树。</li><li>布局：计算渲染树中各元素的位置。</li><li>绘制：将渲染树绘制成页面。</li><li>合成：将页面的各层合成到一起。</li></ol></div><h2 id="二、浏览器的进程模型" tabindex="-1">二、浏览器的进程模型 <a class="header-anchor" href="#二、浏览器的进程模型" aria-label="Permalink to &quot;二、浏览器的进程模型&quot;">​</a></h2><h3 id="_2-1、何为进程" tabindex="-1">2.1、何为进程 <a class="header-anchor" href="#_2-1、何为进程" aria-label="Permalink to &quot;2.1、何为进程&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">进程 Process</p><p></p><ul><li>程序运行需要有它自己专属的内存空间，可以把这块内存空间简单的理解为进程。</li><li>进程是操作系统进行资源分配和调度的基本单位，是程序执行的载体。</li><li>一个进程可以包含多个线程，线程是进程中的实际任务执行者。</li><li>每个应用至少有一个进程，进程之间相互独立，即使要通信，也需要双方同意。</li></ul></div><h3 id="_2-2、何为线程" tabindex="-1">2.2、何为线程 <a class="header-anchor" href="#_2-2、何为线程" aria-label="Permalink to &quot;2.2、何为线程&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">线程 Thread</p><p></p><ul><li>线程是进程中的<code>实际任务执行者</code>，它共享进程的内存空间，可以直接访问进程中的数据。</li><li>线程是操作系统进行资源分配和调度的最小单位，是程序执行的最小单位。</li><li><code>一个进程至少有一个线程</code>，所以在进程开启后会自动创建一个线程来运行代码，该线程称之为主线程。</li><li><code>一个进程可以包含多个线程</code>，线程之间可以共享进程的内存空间，但是每个线程有自己的栈和局部变量。</li></ul></div><h3 id="_2-3、渲染进程" tabindex="-1">2.3、渲染进程 <a class="header-anchor" href="#_2-3、渲染进程" aria-label="Permalink to &quot;2.3、渲染进程&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">作用</p><p></p><ul><li>渲染进程的主要工作是将 HTML、CSS、JavaScript 转换为用户可以看到和操作的视觉效果。</li><li>渲染进程的内部包含多个线程，例如 GUI、JavaScript 引擎、布局和绘制线程等。</li><li>主线程负责处理用户交互事件、子线程的管理和渲染。</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">渲染进程的任务包括但不限于：</p><p></p><ol><li>解析 HTML。</li><li>解析 CSS。</li><li>计算样式。</li><li>布局。</li><li>处理图层。</li><li>每秒把页面画 60 次。</li><li>执行全局 JS 代码。</li><li>执行事件处理函数。</li><li>执行计时器的回调函数。</li></ol></div><div class="tip custom-block github-alert"><p class="custom-block-title">渲染进程调度策略</p><p></p><ol><li>在最开始的时候，渲染主线程会进入一个无限循环</li><li>每一次循环会检查消息队列中是否有任务存在。如果有，就取出第一个任务执行，执行完一个后进入下一次循环；如果没有，则进入休眠状态。</li><li>其他所有线程（包括其他进程的线程）可以随时向消息队列添加任务。新任务会加到消息队列的末尾。在添加新任务时，如果主线程是休眠状态，则会将其唤醒以继续循环拿取任务。</li><li>如此，就可以让每个任务有条不紊的、持续的进行下去了。</li><li>整个过程，被称之为<code>事件循环（消息循环)</code></li></ol></div><h3 id="_2-4、浏览器有哪些进程和线程" tabindex="-1">2.4、浏览器有哪些进程和线程？ <a class="header-anchor" href="#_2-4、浏览器有哪些进程和线程" aria-label="Permalink to &quot;2.4、浏览器有哪些进程和线程？&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">浏览器进程模型</p><p></p><ul><li><code>浏览器主进程</code>（Browser）：负责浏览器的界面显示、用户交互、子进程的管理等。</li><li><code>网络进程</code>（Network）：负责加载网络资源。</li><li><code>渲染进程</code>（Renderer）：负责页面的渲染，解析 HTML、CSS、JavaScript，并绘制页面。</li><li><code>插件进程</code>（Plug-in）：负责插件的运行，例如 Flash。</li></ul></div><h2 id="三、何为事件循环" tabindex="-1">三、何为事件循环 <a class="header-anchor" href="#三、何为事件循环" aria-label="Permalink to &quot;三、何为事件循环&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">概念</p><p></p><ul><li>事件循环是渲染进程的核心(工作方式)。</li><li>它是一种循环（不会结束的 for 循环），不断检查是否有异步任务需要执行，如果有，就将对应的回调函数推入执行栈。</li><li>主线程运行时，如果遇到需要执行的异步任务，就将该任务的回调函数添加到任务队列中。</li><li>当渲染进程空闲时，它会从任务队列中取出一个任务，并放入执行栈中执行。</li><li>如此循环，直到执行栈为空，渲染进程才会休眠，等待下一个任务的到来。</li></ul></div><h2 id="四、何为异步" tabindex="-1">四、何为异步 <a class="header-anchor" href="#四、何为异步" aria-label="Permalink to &quot;四、何为异步&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">概念</p><p></p><ol><li><code>异步</code>是指，代码在执行过程中，一旦遇到一些无法立即处理(需要等待)的任务，就先将该任务的回调函数（即任务的执行结果）存放到消息队列中，然后继续执行后续代码，等到资源返回结果后，再将结果传递给对应的回调函数执行。</li></ol><ul><li>计时完成后需要执行的任务 —— <code>setTimeout</code>、<code>setInterval</code></li><li>网络通信完成后需要执行的任务 -- <code>XHR</code>、<code>Fetch</code></li><li>用户操作后需要执行的任务 -- <code>addEventListener</code></li><li>如果让渲染主线程等待这些任务的时机达到，就会导致主线程长期处于「阻塞」的状态，从而导致浏览器「卡死」。</li><li>为了解决这个问题，引入了事件循环机制，将这些异步任务的执行结果存放到消息队列中，主线程再从消息队列中取出执行。</li></ul></div><h3 id="_4-1、如何理解异步" tabindex="-1">4.1、如何理解异步 <a class="header-anchor" href="#_4-1、如何理解异步" aria-label="Permalink to &quot;4.1、如何理解异步&quot;">​</a></h3><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><ol><li>JS是一门单线程的语言，这是因为它运行在浏览器的渲染主线程中，而渲染主线程只有一个。</li><li>而渲染主线程承担着诸多的工作，渲染页面、执行 JS 都在其中运行。</li><li>如果使用同步的方式，就极有可能导致主线程产生阻塞，从而导致消息队列中的很多其他任务无法得到执行。</li><li>这样一来，一方面会导致繁忙的主线程白白的消耗时间，另一方面导致页面无法及时更新，给用户造成卡死现象。</li><li>所以浏览器采用异步的方式来避免。具体做法是当某些任务发生时，比如计时器、网络、事件监听，主线程将任务交给其他线程去处理，自身立即结束任务的执行，转而执行后续代码。</li><li>当其他线程完成时，将事先传递的回调函数包装成任务，加入到消息队列的末尾排队，等待主线程调度执行。在这种异步模式下，浏览器永不阻塞，从而最大限度的保证了单线程的流畅运行。</li></ol></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>异步的实现主要是通过回调函数实现的。</li><li>回调函数就是将任务的执行结果作为参数传入到函数中，待任务执行完毕后，再执行回调函数。</li><li>回调函数的优点是简单、灵活，缺点是不利于代码的阅读和维护。</li><li>为了解决这个问题，引入了 Promise 和 Generator。</li></ul></div><h2 id="五、js为何会阻碍渲染" tabindex="-1">五、JS为何会阻碍渲染 <a class="header-anchor" href="#五、js为何会阻碍渲染" aria-label="Permalink to &quot;五、JS为何会阻碍渲染&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ol><li>任务没有优先级，在消息队列中先进先出但消息队列是有优先级的。</li><li>每个任务都有一个任务类型，同一个类型的任务必须在一个队列，不同类型的任务可以分属于不同的队列。在一次事件循环中，浏览器可以根据实际情况从不同的队列中取出任务执行。</li><li>浏览器必须准备好一个微队列，微队列中的任务优先所有其他任务执行</li></ol></div><h2 id="六、浏览器的队列" tabindex="-1">六、浏览器的队列 <a class="header-anchor" href="#六、浏览器的队列" aria-label="Permalink to &quot;六、浏览器的队列&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><ul><li>微队列：用户存放需要最快执行的任务，优先级「最高」 ,<code>Promise</code>、<code>MutationObserver</code></li><li>交互队列：用于存放用户操作后产生的事件处理任务，优先级「高」</li><li>延时队列：用于存放计时器到达后的回调任务，优先级「中」</li><li>其他队列：其他类型的任务，优先级「低」</li></ul></div>',25)]))}const b=i(o,[["render",c]]);export{n as __pageData,b as default};
